'use strict';
const assessmentBank=[],assessmentBankVersion=2;
function addAssessmentQuestion(id,domainId,difficulty,kind,stem,choices,correct,explanation,extra={}){const q={id,domainId,difficulty,kind,stem,options:choices.map((text,i)=>({id:'o'+i,text:String(text)})),correct:correct.map(i=>'o'+i),explanation,...extra};assessmentBank.push(q);return q}
// Reuse the authored curriculum, examples and acceptance criteria; no remote AI calls.
for(const t of keywordCatalog){const d=termPractice[t.zh],others=keywordCatalog.filter(x=>x.domainId===t.domainId&&x.id!==t.id);const pick=(field)=>{const used=new Set([field(t)]),out=[];for(let offset=0;offset<others.length&&out.length<3;offset++){const x=others[(offset*7+keywordCatalog.indexOf(t))%others.length],text=field(x);if(!used.has(text)){used.add(text);out.push(text)}}for(const x of others){const text=field(x);if(out.length<3&&!used.has(text)){used.add(text);out.push(text)}}return out};addAssessmentQuestion('term-'+t.id,t.domainId,'入門','single',`下列哪項最符合「${t.zh}（${t.en}）」的定義？`,[t.definition,...pick(x=>x.definition)],[0],`${t.zh}（${t.en}）：${t.definition}\n實例：${d.example}`,{source:'詞條定義',termId:t.id,lessonId:t.lessonId});addAssessmentQuestion('case-'+t.id,t.domainId,'基礎','single',`情境：${d.example}\n針對這個情境，哪一項敘述最能正確說明「${t.zh}（${t.en}）」的特性或結果？`,[d.expected,...pick(x=>termPractice[x.zh].expected)],[0],`判讀依據：${d.expected}\n題目情境：${d.example}\n延伸操作（作答不需預先執行）：${d.action}`,{source:'情境應用',termId:t.id,lessonId:t.lessonId})}
for(const l of lessons)addAssessmentQuestion('course-'+l.id,l.domainId??([0,1,0,1,3,3,5,5,4,4,7,6,8,9,10,10,11,12,15,15,11,7,17,0][l.id]),l.id<24?'入門':'基礎','single',l.q,l.answers,[l.correct],l.body,{source:'課程檢核',lessonId:l.id});
function numericalQuestion(id,domain,stem,values,result,explanation,steps,topic){const correct=String(result),choices=[correct];for(const v of values){const s=String(v);if(!choices.includes(s))choices.push(s);if(choices.length===4)break}if(choices.length!==4)throw Error('計算題選項不足：'+id);return addAssessmentQuestion('calc-'+id,domain,'進階','single',stem,choices,[0],explanation,{source:'數值計算',steps,topic})}
function worked(op,a,b,result,formula){return {step:0,formula,substitution:`${a} ${op} ${b}`,result:String(result),math:{kind:'binary',op,operands:[a,b]}}}
for(let i=1;i<=8;i++){
 const x=i,w=2,b=1,z=w*x+b;numericalQuestion('neuron-'+i,4,`神經元（Neuron）使用 z=wx+b，x=${x}、w=2、b=1。線性分數 z 為多少？`,[2*x,2*x-1,x+1,z+3],z,`先算 wx=2×${x}=${2*x}，再加偏置 1，得到 ${z}。`,[worked('*',2,x,2*x,'w*x'),worked('+',2*x,1,z,'w*x+b')],'神經元');
 const ww=i-4,g=2*(ww-3),next=ww-.5*g;numericalQuestion('gradient-'+i,5,`損失 L(w)=(w−3)²，w=${ww}、學習率 η=0.5。以梯度下降（Gradient Descent）更新一次後，w 為多少？`,[ww+.5*g,ww-g,ww+1,9,-9],next,`梯度 g=2(w−3)=${g}；w新=w−0.5g=${next}。`,[worked('-',ww,3,ww-3,'w-3'),worked('*',2,ww-3,g,'2*(w-3)'),worked('*',.5,g,.5*g,'v.lr*g'),worked('-',ww,.5*g,next,'v.w-v.lr*g')],'梯度下降');
 const a=i+1,tp=a,fp=a,precision=.5;numericalQuestion('precision-'+i,6,`分類模型的真陽性 TP=${tp}、假陽性 FP=${fp}。精確率（Precision）為多少？`,[1,0,.25,.75],precision,`Precision=TP/(TP+FP)=${tp}/${tp+fp}=0.5。`,[worked('+',tp,fp,tp+fp,'tp+fp'),worked('/',tp,tp+fp,.5,'tp/(tp+fp)')],'精確率');
 const n=10+i*2,k=3,out=n-k+1;numericalQuestion('conv-'+i,7,`方形輸入邊長 N=${n}，卷積核 K=3，步幅 S=1、填補 P=0、dilation=1。卷積（Convolution）輸出邊長是多少？`,[n,n-3,n+2,n+3],out,`O=⌊(N+2P−K)/S⌋+1=(${n}−3)+1=${out}。`,[worked('-',n,3,n-3,'v.size-v.kernel'),worked('+',n-3,1,out,'o+1')],'卷積');
 const e=i,mse=e*e;numericalQuestion('mse-'+i,6,`兩筆回歸誤差分別為 ${e} 與 −${e}。均方誤差（Mean Squared Error, MSE）為多少？`,[2*mse,e,2*e,mse+1,mse+2,mse+3,mse+4],mse,`MSE=(${e}²+(−${e})²)/2=${2*mse}/2=${mse}。`,[worked('**',e,2,mse,'v.e1**2'),worked('**',-e,2,mse,'v.e2**2'),worked('+',mse,mse,2*mse,'v.e1*v.e1+v.e2*v.e2'),worked('/',2*mse,2,mse,'(v.e1*v.e1+v.e2*v.e2)/2')],'均方誤差');
 const m=10*i,nn=20,rank=2,p=rank*(m+nn);numericalQuestion('lora-'+i,12,`只更新一個 m×n 線性層的 LoRA（Low-Rank Adaptation）。m=${m}、n=${nn}、rank=2，且不計偏置，可訓練參數量是多少？`,[m*nn,2*m*nn,m+nn,p+2,p+4],p,`LoRA 兩個低秩矩陣的參數合計 r(m+n)=2(${m}+20)=${p}。`,[worked('+',m,nn,m+nn,'v.m+v.n'),worked('*',rank,m+nn,p,'v.rank*(v.m+v.n)')],'低秩適應');
 const samples=10*i+1,batch=10,micro=Math.ceil(samples/batch);numericalQuestion('batch-'+i,5,`資料有 ${samples} 筆，批次大小（Batch Size）為 10，保留最後不完整批次。每輪微批次數是多少？`,[Math.floor(samples/batch),samples,batch,micro+2],micro,`保留尾批，因此向上取整 ceil(${samples}/10)=${micro}。`,[worked('/',samples,batch,samples/batch,'v.samples/v.batch'),{step:0,formula:'Math.ceil(samples/batch)',substitution:'ceil',result:String(micro),math:{kind:'function',op:'ceil',operands:[samples/batch]}}],'批次大小');
 const val=20+5*i,mean=20,std=5,zz=i;numericalQuestion('zscore-'+i,1,`以訓練集平均 μ=20、標準差 σ=5 標準化（Standardization）。x=${val} 的 z-score 是多少？`,[val-mean,val/std,zz+1,-zz,zz+2],zz,`z=(x−μ)/σ=(${val}−20)/5=${zz}。`,[worked('-',val,mean,val-mean,'v.x-v.mean'),worked('/',val-mean,std,zz,'(v.x-v.mean)/v.std')],'標準化');
}
